import { expect, test, uniqueName } from "../../fixtures";

const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

for (const { field, value } of examples) {
  test(`rejects ${field} set to ${JSON.stringify(value)} with validation_error`, { tag: "@VEN-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const valid = {
      name: uniqueName("Invalid Field Vendor"),
      category: "software",
      contact_email: "billing@vendor.test",
    };
    const body = { ...valid, [field]: value };

    // Act
    const response = await member.post("/api/vendors", { data: body });

    // Assert
    expect(response.status()).toBe(422);
    const json = await response.json();
    expect(json.error?.code).toBe("validation_error");
    expect(JSON.stringify(json)).toContain(`"${field}"`);
  });
}
